            } else {
                cur = 0;                    // 遇到 '*' 说明这一段结束
            }
        }

        // 长度 L 的一笔：每秒两头各擦 1 厘米，长度降到 1 或 2 时下一
        // 秒整段擦掉，所以正好是 ceil(L / 2)，即整数除法 (L + 1) / 2
        cout << (best + 1) / 2 << "\n";
    }
    return 0;
}
```

